const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),path=x=>encodeURI(x)+(/\.(jpe?g|png)$/i.test(x)?'?v=30':''),delay=ms=>new Promise(r=>setTimeout(r,ms)),pause=async()=>{if(settings.speed==='instant')return;let attack=s?.fx?.type==='attack',same=attack&&lastAttackPause===s.fx;lastAttackPause=attack?s.fx:null;await delay(settings.speed==='fast'?(attack&&!same?430:60):(attack?(same?90:850):240))},safeSave=()=>{try{localStorage.setItem(SAVE,JSON.stringify(engine.state()))}catch(e){notice('Salvataggio locale non disponibile')}};
function audio(){try{if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();if(!musicTimer){let i=0;musicTimer=setInterval(()=>{if(!settings.music||document.hidden)return;let seq=[130.81,155.56,196,146.83,130.81,174.61,196,155.56];tone(seq[i++%seq.length],1.6,settings.music/100*.018,'sine');tone(seq[(i+3)%seq.length]*.5,2,settings.music/100*.009,'triangle')},1800)}}catch(e){}}
function tone(f,d,vol,type='triangle'){if(!ctx||!vol)return;try{let o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime;o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0001,vol),t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(ctx.destination);o.start();o.stop(t+d+.02)}catch(e){}}
