let lastFx='',lastVisual=null;const engine=createEngine(db,{choose,update:state=>{let old=lastVisual;s=state;let previousFx=lastFx,nextFx=JSON.stringify(state.fx);if(nextFx!==lastFx&&state.fx){fx()}lastFx=nextFx;if(screen==='game'){let oldRects={};if(old)for(let h of old.players.flatMap(p=>p.party)){let el=app.querySelector('[data-hero="'+h.id+'"]');if(el)oldRects[h.id]=el.getBoundingClientRect()}renderGame();visualChanges(old,state,oldRects);if(nextFx!==previousFx&&state.fx?.type==='attack')attack21(state.fx)}lastVisual=JSON.parse(JSON.stringify(state))},pause});
