function visualChanges(old,now,rects){if(!old||now.turnNo<old.turnNo||settings.speed==='instant')return;for(let p=0;p<2;p++){let before=old.players[p],after=now.players[p];for(let h of after.party){let el=app.querySelector('[data-hero="'+h.id+'"]'),prev=before.party.find(a=>a.id===h.id);if(!prev){el?.classList.add('arrive');floatAt(el,'RECLUTATO','heal')}else if(h.hp!==prev.hp){let n=h.hp-prev.hp;floatAt(el,(n>0?'+':'')+n,n>0?'heal':'hit')}}for(let h of before.party)if(!after.party.some(a=>a.id===h.id))floatAt(null,'CADUTO','hit',rects[h.id]);for(let r of engine.resources){let n=after.resources[r]-before.resources[r];if(n>0){let target=app.querySelector('[data-resource="'+p+'-'+r+'"]');floatAt(target,'+'+n+' '+r,'heal');resourceFlight(target,r,n)}}}for(let k of engine.tiers){let a=old.revealed[k],b=now.revealed[k];if(a&&b&&a.id===b.id&&a.hp!==b.hp){let el=app.querySelector('[data-monster="'+k+'"]'),n=b.hp-a.hp;floatAt(el,(n>0?'+':'')+n,n>0?'heal':'hit');if(n<0&&now.fx?.type!=='attack'){let slash=document.createElement('span');slash.className='slash';el?.append(slash);setTimeout(()=>slash.remove(),400)}}}}

async function choose(p,title,options){if(p===1){let o=[...options].sort((a,b)=>(b.score||0)-(a.score||0));return o[0]?.value}return new Promise(resolve=>{let d=dialog(title,'<p>Scegli come procedere.</p>');let items=options.map(o=>[o.label,()=>{close();resolve(o.value)},o.value===null||o.value===false?'':'primary']);buttons(d,items);let c=Object.values(engine.cards).find(x=>title.startsWith(x.nome+' —'));if(c){let det=document.createElement('details');det.innerHTML=`<summary>Leggi la carta</summary><img alt="${esc(c.nome)}" src="${fullCard(c)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'" style="max-height:38dvh;max-width:100%;object-fit:contain"><p>${esc(c.abilita.testo_ufficiale||c.abilita.testo_stampato)}</p>`;d.append(det)}else if(title.includes('Reazione')||title.includes('Proteggere')){let relevant=options.map(o=>engine.cards[o.value]).filter(Boolean);if(relevant.length){let det=document.createElement('details');det.innerHTML='<summary>Abilità disponibili</summary>'+relevant.map(c=>`<p><strong>${esc(c.nome)}</strong>: ${esc(c.abilita.testo_ufficiale||c.abilita.testo_stampato)}</p>`).join('');d.append(det)}}})}
function renderMenu(){screen='menu';close();app.innerHTML=`<div class="menu-wrap"><div class="menu" aria-label="Heroes and Monsters"><button class="menu-hot" data-menu="new" style="top:40.5%" aria-label="Nuova partita">NUOVA PARTITA</button><button class="menu-hot" data-menu="continue" style="top:55.7%" aria-label="Continua partita">CONTINUA PARTITA</button><button class="menu-hot" data-menu="settings" style="top:70.7%" aria-label="Impostazioni">IMPOSTAZIONI</button><span class="version">BUILD 4.0 • Avvio Fix</span></div></div>`;app.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{audio();if(b.dataset.menu==='new')newGame();if(b.dataset.menu==='continue')continueGame();if(b.dataset.menu==='settings')openSettings()})}
function newGame(){let next=()=>{let d=dialog('NUOVA PARTITA','<p>1 giocatore contro la CPU · scegli il tuo mazzo Eroe iniziale.</p>');buttons(d,engine.classes.map(c=>[symbols[c]+' '+c,()=>{close();screen='game';lastVisual=null;run(()=>engine.start(c,engine.classes[Math.floor(Math.random()*engine.classes.length)]))},'primary']));buttons(d,[['Annulla',close]])};if(localStorage.getItem(SAVE))confirmBox('Nuova partita','Sovrascrivere la partita salvata?',next);else next()}
function continueGame(){try{let data=JSON.parse(localStorage.getItem(SAVE)||'null');if(!data){notice('Nessuna partita salvata');return}screen='game';s=engine.load(data);lastVisual=JSON.parse(JSON.stringify(s));renderGame();kick()}catch(e){notice('Salvataggio non disponibile')}}
function fullCard(c){return c.tipo==='eroe'?'full25_'+c.id+'.jpg':path(c.immagine)}
function cardFallback(c){let el=document.createElement('div');el.className='full25-fallback';el.innerHTML=`<strong>${esc(c.nome)}</strong><img src="${path(c.ritratto)}" alt=""><b>♥ ${c.vita_massima} · ⚔ ${c.danno_base}</b><strong>${esc(c.abilita.nome)}</strong><p>${esc(c.abilita.testo_ufficiale||c.abilita.testo_stampato)}</p>`;return el}
async function revealNew(before){if(!before||settings.speed==='instant'||screen!=='game')return;let after=engine.state();for(let i=0;i<2;i++){for(let h of after.players[i].party.filter(h=>!before.players[i].party.some(x=>x.id===h.id))){let c=engine.cards[h.id];await new Promise(resolve=>{let layer=document.createElement('div');layer.className='reveal15 reveal24';layer.style.setProperty('--glow',palette[c.categoria]);layer.innerHTML=`<div class="reveal15-inner"><div class="reveal15-title">${i?'CPU · ':''}EVOCAZIONE EROE</div><div class="reveal24-card"><img alt="Retro ufficiale" src="hm21-back.jpg"></div><strong>${esc(c.nome)}</strong><button class="primary" disabled>CONTINUA</button></div>`;document.body.append(layer);let card=layer.querySelector('.reveal24-card'),img=card.querySelector('img'),btn=layer.querySelector('button'),closed=false,timer;let done=()=>{if(closed)return;closed=true;clearTimeout(timer);layer.remove();resolve()};btn.onclick=done;let face=new Image();face.alt=c.nome;face.className='hm27-face';let shown=false;let reveal=()=>{if(closed||shown)return;shown=true;let front=face.complete&&face.naturalWidth?face:cardFallback(c);card.replaceChildren(front);card.style.transform='none';card.classList.add('hm27-shown');btn.disabled=false;if(i===1)timer=setTimeout(done,settings.speed==='fast'?650:1400)};face.onload=()=>{};face.src=fullCard(c)+'?v=30';setTimeout(()=>{if(closed)return;card.classList.add('hm27-turn');setTimeout(()=>{if(face.complete)reveal();else{face.onload=reveal;face.onerror=reveal;setTimeout(reveal,1800)}},220)},250);});}}}
async function run(fn){if(busy)return;busy=true;renderIfGame();try{let before=s?JSON.parse(JSON.stringify(s)):null;let result=await fn();s=engine.state();safeSave();await revealNew(before)}catch(e){notice(e.message);try{s=engine.state()}catch(_){} }finally{busy=false;renderIfGame()}kick()}
function renderIfGame(){if(screen==='game'&&s)renderGame()}
function dieFace(n){let pts={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]}[n];return pts?`<span class="pipface" aria-label="${n}">${Array.from({length:9},(_,i)=>`<i class="${pts.includes(i)?'on':''}"></i>`).join('')}</span>`:esc(n??'–')}
function heroSlot(h,p){if(!h)return '<div class="slot">×</div>';let c=engine.cards[h.id],aura=engine.bonus(p,c.categoria),avail=p===0&&!busy&&s.turn===0&&engine.canActivate(h),fx=s.fx?.hero===h.id?s.fx:null;return `<button class="hero ${fx?'attacking21':''} ${aura?'aura':''} ${avail?'ready':''}" data-hero="${h.id}" data-owner="${p}" style="--class:${palette[c.categoria]}" aria-label="${esc(c.nome)}"><img alt="" src="${path(c.ritratto)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'"><div class="life42" style="--life:${Math.max(0,Math.min(100,100*h.hp/c.vita_massima))}%"></div><div class="hero-info"><div class="hero-name">${esc(c.nome)}</div><div class="stat"><span class="hp">♥ ${h.hp}</span><span class="atk">⚔ ${engine.dmg(h)}</span>${h.bounty!==undefined?'♜':''}</div></div>${fx?`<span class="die ${fx.result}">${dieFace(fx.roll)}</span>`:''}</button>`}
function playerBar(p){let v=s.players[p];return `<div class="playerbar"><span class="player-name">${p?'CPU':'TU'}${s.turn===p?' · ●':''}</span><div class="resources">${engine.resources.map(r=>`<span data-resource="${p}-${r}" title="${r}">${resIcons[r]} ${r} <b>${v.resources[r]}</b></span>`).join('')}</div><span class="vp"><span class="gems">${Array.from({length:6},(_,i)=>`<i class="${i<v.points?'lit':''}"></i>`).join('')}</span> ${v.points}/6</span></div>`}
