function monsterDeck(k){let m=s.revealed[k],c=m&&engine.cards[m.id],active=s.battle?.tier===k;return `<button class="monster ${c?'revealed':'covered'} ${active?'active':''}" data-monster="${k}" aria-label="${k}${c?' '+esc(c.nome):''}">${c?`<img class="mimage" src="${path(c.ritratto)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'" alt=""><span class="tier-tag">${esc(k)} · ${active?'IN SCONTRO':'SCOPERTO'}</span><div class="monster-info"><div class="mname">${esc(c.nome)}</div><div class="stat"><span class="hp">♥ ${m.hp}</span><span class="atk">⚔ ${m.damage+(c.nome==='Il Colosso del Vuoto'&&active&&s.battle.round%2===1?1:0)}</span></div>${aff(c)}</div>`:`<img class="deck-art31" src="${'hm54-'+k+'.webp'}" alt="${k}: ${engine.req[k]} Eroi">`}</button>`}
let arenaKey=null;
function arena(){let k=s.battle.tier,m=s.revealed[k],c=engine.cards[m.id],key=s.battle.id+'-'+k,enter=arenaKey!==key;arenaKey=key;let def=s.battle.defense??(s.fx?.type==='defense'?s.fx.roll:s.fx?.def);return `<button class="hm14-arena ${enter?'arena-enter':''}" data-monster="${k}" aria-label="${esc(c.nome)}"><img class="hm14-art" src="${path(c.ritratto)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'" alt=""><div class="hm14-top"><span>${esc(k)} · ROUND ${s.battle.round||1}</span><span class="monster-die ${s.fx?.type==='defense'?'rolling':''}"><small>DIFESA</small><b>${dieFace(def)}</b></span></div><div class="hm14-bottom"><strong>${esc(c.nome)}</strong><div class="arena-stats"><span class="hp">♥ ${m.hp}/${c.vita_massima}</span><span class="atk">⚔ ${m.damage+(c.nome==='Il Colosso del Vuoto'&&s.battle.round%2===1?1:0)}</span></div><div class="arena-effect">${esc(c.abilita.nome)}: ${esc(c.abilita.testo_ufficiale||c.abilita.testo_stampato)}</div>${aff(c)}</div></button>`}
async function startFight(k){engine.fight(k);s=engine.state();renderGame();await delay(1000);return engine.round()}
function renderGame(){if(!s)return;if(s.phase==='finished'&&!busy){renderEnd();return}if(!s.battle)arenaKey=null;let human=s.turn===0,phase=s.phase,can=!busy&&human,labels={recruit:'FASE ABILITÀ',ability:'PASSA ALL’IMPRESA',quest:'TERMINA TURNO',combat:'LANCIA I DADI',roundEnd:'CONTINUA'},status=s.log.at(-1)||'',r=s.battle?.round||0;app.innerHTML=`<div class="board premium20 definitive30">${partyRow(1)}<section class="mid ${s.battle?'in-battle':''}"><div class="panel monster-panel">${s.battle?'<div class="mini-title">ARENA MOSTRO</div>':''}<div class="monster-decks ${s.battle?'merged':''}">${s.battle?arena():engine.tiers.map(monsterDeck).join('')}</div></div><div class="panel controls"><div class="phase">${human?phaseNames[phase]:'TURNO AVVERSARIO'}</div>${s.battle?`<div class="dice-defense">ROUND ${phase==='combat'&&!busy?r+1:r||1}${s.fx?.roll&&s.fx.type==='defense'?' · D '+s.fx.roll:s.fx?.def?' · D '+s.fx.def:''}</div>`:''}${human&&phase==='ability'?`<div class="ability-hint">Tocca un Eroe illuminato per attivare la sua abilità. ${s.players[0].party.filter(h=>engine.canActivate(h)).length} disponibili.</div>`:''}<div class="status" title="${esc(status)}">${esc(status)}</div>${can&&labels[phase]?`<button class="primary" data-next>${labels[phase]}</button>${phase==='roundEnd'?'<button class="danger" data-retreat>RITIRATA</button>':''}`:`<div class="empty-message">${busy?'Elaborazione…':human?'':'CPU in azione'}</div>`}<div class="top-tools"><button data-log>▤ Registro</button><button data-discard>▱ Scarti ${s.discard.length}</button><button data-home ${busy?'disabled':''}>Menù</button></div></div><div class="panel recruitment-panel"><div class="hero-decks">${engine.classes.map(k=>`<button class="deck" style="--class:${palette[k]}" data-deck="${k}" ${!can||phase!=='recruit'?'disabled':''}><img class="deck-art31" src="hm52-${k}.webp" alt="${k}"></button>`).join('')}</div></div></section>${partyRow(0)}</div>${s.fx?.type==='victory'?'<div class="victory-flash">MOSTRO SCONFITTO!</div>':''}`;
 app.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{audio();inspect(engine.cards[b.dataset.hero],Number(b.dataset.owner))});app.querySelectorAll('[data-monster]').forEach(b=>b.onclick=()=>{audio();clickMonster(b.dataset.monster)});app.querySelectorAll('[data-deck]').forEach(b=>b.onclick=()=>{audio();clickDeck(b.dataset.deck)});let bind=(sel,fn)=>{let b=app.querySelector(sel);if(b)b.onclick=()=>{audio();fn()}};bind('[data-next]',()=>run(async()=>{if(phase==='recruit'||phase==='ability')return engine.next();if(phase==='quest')return engine.end();if(phase==='roundEnd'){engine.resume();return engine.round()}if(phase==='combat')return engine.round()}));bind('[data-retreat]',()=>confirmBox('Ritirata','Il Mostro conserverà Vita e Danno. Terminare il turno?',()=>run(()=>engine.retreat())));bind('[data-home]',()=>{safeSave();renderMenu()});bind('[data-log]',showLog);bind('[data-discard]',()=>archive('SCARTI',s.discard.map(h=>engine.cards[h.id]),()=>close()));
}
function clickDeck(k){if(busy||s.turn!==0||s.phase!=='recruit')return;let r=db.regole_progetto.archetipi[k].risorsa,reason=s.players[0].party.length>=8?'PARTY AL COMPLETO':!s.decks[k].length?'MAZZO ESAURITO':s.players[0].resources[r]<2?'RISORSE INSUFFICIENTI':'';confirmBox('Reclutare un Eroe '+k+'?',reason||`Costo: 2 ${r}`,()=>run(()=>engine.recruit(k)),!!reason)}
function clickMonster(k){let m=s.revealed[k],c=m&&engine.cards[m.id];if(c&&(busy||s.turn!==0||s.phase!=='quest')){inspect(c,null,k);return}if(!busy&&s.turn===0&&s.phase==='quest'){let reason=!engine.eligible(0,k)?`Servono ${engine.req[k]} Eroi vivi.`:!m&&!s.decks[k].length?'Mazzo esaurito.':'';let d=dialog('Vuoi affrontare un Mostro '+k+'?',`<p>${esc(reason||'Inizia l’impresa.')}</p>${c?`<p>${esc(c.nome)} · ${m.hp} Vita</p>${aff(c)}`:''}`);buttons(d,[['Sì',()=>{close();run(async()=>{return startFight(k)})},'primary',!!reason],['No',close],...(c?[['Consulta carta',()=>inspect(c,null,k)]]:[])])}else if(c)inspect(c,null,k);else notice('Mazzo '+k+' · '+s.decks[k].length+' Mostri')}
function inspect(c,p=null,tier=null,back=null){let h=p!==null?s?.players[p].party.find(h=>h.id===c.id):null,m=tier?s?.revealed[tier]:null,avail=h&&p===0&&s.turn===0&&!busy&&engine.canActivate(h),a=c.abilita;let desc=`<p><b>${esc(a.nome)}</b></p><p>${esc(a.testo_ufficiale||a.testo_stampato)}</p>${h?`<p>Vita attuale: <b>${h.hp}/${c.vita_massima}</b> · Danno: <b>${engine.dmg(h)}</b></p>`:''}${m?`<p>Vita attuale: <b>${m.hp}/${c.vita_massima}</b> · Danno: <b>${m.damage}</b></p>`:''}${c.tipo==='mostro'?aff(c)+`<p>Ricompensa: ${c.ricompensa.punti_vittoria} Punti Vittoria · ${c.ricompensa.risorse_casuali} risorse</p>`:''}${h?`<p>${avail?'Abilità disponibile':a.tipo_proposto==='passiva'?'Abilità passiva automatica':p===1?'Eroe avversario': s.turn!==0?'Attendi il tuo turno':s.phase==='recruit'?'Premi FASE ABILITÀ dopo il reclutamento':s.phase!=='ability'?'Disponibile nella fase Abilità':c.id==='guerrieri_gormak'&&engine.total(1)===0?'La CPU non possiede risorse da rubare':h.used?.turn===s.turnNo?'Già utilizzata in questo turno':'Condizioni non soddisfatte'}</p>`:''}`;let d=dialog(c.nome,`<div class="inspect"><img alt="${esc(c.nome)}" src="${fullCard(c)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'"><div class="desc">${desc}<div class="inspect-actions"></div></div></div>`,true);modal.onclick=e=>{if(e.target===modal)(back||close)()};let act=d.querySelector('.inspect-actions');buttons(act,[...(avail?[['ATTIVA ABILITÀ',()=>{close();run(()=>engine.activate(c.id))},'primary']]:[]),...(m&&!busy&&s.turn===0&&s.phase==='quest'&&engine.eligible(0,tier)?[['AFFRONTA',()=>{close();run(async()=>{return startFight(tier)})},'primary']]:[]),['Chiudi',back||close]])}
function archive(title,list,back){let d=dialog(title,`<div class="archive">${list.map(c=>`<button data-id="${c.id}"><img loading="lazy" src="${path(c.ritratto)}" onerror="this.onerror=null;this.src='${path(c.immagine)}'" alt=""><div>${esc(c.nome)}</div></button>`).join('')||'<p>Nessuna carta.</p>'}</div>`,true);d.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>inspect(engine.cards[b.dataset.id],null,null,()=>archive(title,list,back)));buttons(d,[['Indietro',back]])}
