function openSettings(){let d=dialog('IMPOSTAZIONI',`<div class="settings"><label for="music">Musica</label><input id="music" type="range" min="0" max="100" value="${settings.music}"><label for="effects">Effetti</label><input id="effects" type="range" min="0" max="100" value="${settings.effects}"><label for="speed">Animazioni</label><select id="speed"><option value="normal">Normali</option><option value="fast">Veloci</option><option value="instant">Istantanee</option></select><label for="vibration">Vibrazione</label><input id="vibration" type="checkbox" ${settings.vibration?'checked':''}></div>`);d.querySelector('#speed').value=settings.speed;for(let k of ['music','effects','speed','vibration'])d.querySelector('#'+k).oninput=e=>{let v=e.target;settings[k]=k==='vibration'?v.checked:k==='speed'?v.value:Number(v.value);try{localStorage.setItem(SET,JSON.stringify(settings))}catch(_){}if(k==='effects')fx()};buttons(d,[['Regolamento',rules],['Archivio Eroi',()=>archive('60 EROI',db.eroi,openSettings)],['Bestiario',()=>archive('15 MOSTRI',db.mostri,openSettings)],['Indietro',close]])}
function rules(){let d=dialog('REGOLAMENTO',`<div class="loglist"><p>Competitivo, 2 giocatori nella versione offline. Vince il primo a 6 Punti Vittoria.</p><p>Ogni turno: 2 risorse casuali, Reclutamento (2 risorse dell’archetipo), fase Abilità, Impresa. Massimo 8 Eroi. Nessuna carta Evento.</p><p>Base: almeno 3 Eroi, 1 punto e 2 risorse; Intermedi: 5 Eroi, 2 punti e 4 risorse; Elite: 7 Eroi, 3 punti e 6 risorse.</p><p>All’inizio di ciascun round il Mostro tira un D6 di difesa. Gli Eroi attaccano da sinistra a destra con D6: maggiore = danno al Mostro; minore = danno all’Eroe; pari = nessun danno, salvo abilità specifiche. Il risultato modificato resta fra 1 e 6.</p><p>Debolezza +1 Danno, Resistenza −1 Danno (minimo zero). La ritirata conserva Vita e Danno del Mostro per entrambi i giocatori. La morte sposta gli Eroi negli scarti.</p>${Object.values(db.regole_progetto.archetipi).map(a=>`<p><b>${esc(a.nome_bonus)}</b>: ${esc(a.bonus)}</p>`).join('')}<p>Reazioni: una risposta per azione avversaria, nessuna reazione a una reazione, massimo una reazione per Eroe per turno. Le singole abilità sono consultabili nell’archivio.</p><p>Garrek: utilizzi illimitati e cumulabili. Malzar: resurrezione a 1 Vita. Rowan: danno automatico nel round successivo e attacco normale.</p></div>`);buttons(d,[['Indietro',openSettings]])}
function renderEnd(){screen='game';let win=s.winner===0,st=s.players[0].stats;app.innerHTML=`<section class="end-screen"><div><h1 class="${win?'':'loss'}">${win?'VITTORIA':'SCONFITTA'}</h1><p>Tu ${s.players[0].points} ★ · CPU ${s.players[1].points} ★</p><p>Mostri sconfitti: ${st.kills} · Eroi reclutati: ${st.recruited} · Eroi caduti: ${st.fallen||0}</p><div class="choices"><button data-new>NUOVA PARTITA</button><button data-menu>MENÙ PRINCIPALE</button></div></div></section>`;app.querySelector('[data-new]').onclick=newGame;app.querySelector('[data-menu]').onclick=renderMenu}
