function estimate(k){let p=1,a=s.players[p].party,m=s.revealed[k],c=m?engine.cards[m.id]:null,defense=3.5,damage=a.reduce((sum,h)=>{let cls=engine.cards[h.id].categoria,d=engine.dmg(h)+(cls==='Maghi'&&engine.bonus(p,'Maghi')?1:0);if(c&&h.id!=='ranger_orin')d+=(c.debolezze.includes(cls)?1:c.resistenze.includes(cls)?-1:0);return sum+Math.max(0,d)*(cls==='Ranger'&&engine.bonus(p,'Ranger')?.58:.42)},0),hp=m?.hp??({Base:13,Intermedi:20,Elite:25}[k]),harm=m?.damage??({Base:2,Intermedi:2,Elite:3}[k]),life=a.reduce((n,h)=>n+h.hp,0),reward=db.regole_progetto.ricompense_mostri[k].punti_vittoria,rounds=hp/Math.max(.5,damage);return {score:reward*3-rounds*.9+(m?1.2:0)+(s.players[p].points+reward>=6?3:0)-Math.max(0,rounds*a.length*.4*harm-life*.65)*.25,rounds,damage,life,harm,hp}}
async function cpuAction(){let p=s.players[1],phase=s.phase;if(phase==='recruit'){let ks=engine.classes.filter(k=>s.decks[k].length&&p.resources[db.regole_progetto.archetipi[k].risorsa]>=2&&p.party.length<8);if(ks.length){let k=ks.sort((a,b)=>p.party.filter(h=>engine.cards[h.id].categoria===b).length-p.party.filter(h=>engine.cards[h.id].categoria===a).length)[0];return engine.recruit(k)}return engine.next()}
 if(phase==='ability'){let good=p.party.filter(h=>engine.canActivate(h)).filter(h=>{let k=h.id.split('_').slice(1).join('_');if(k==='orin_il_veggente'||k==='thalwen'||k==='edrik')return k==='edrik';if(k==='garrek')return p.party.length>=4&&engine.total(1)>=5&&p.drums<2;if(['neris','morwen','drakor','sable'].includes(k))return h.hp>1;if(k==='malakar')return s.players[0].party.length>=3&&s.players[0].party.some(x=>engine.dmg(x)>=3);if(k==='malzar')return h.hp>3;return true});if(good.length)return engine.activate(good[0].id);return engine.next()}
 if(phase==='quest'){let choices=engine.tiers.filter(k=>(s.revealed[k]||s.decks[k].length)&&engine.eligible(1,k)).map(k=>({k,...estimate(k)})).sort((a,b)=>b.score-a.score);if(choices.length&&choices[0].score>-1.8){return startFight(choices[0].k)}return engine.end()}
 if(phase==='combat')return engine.round();if(phase==='roundEnd'){let e=estimate(s.battle.tier);if(e.rounds>2.4&&e.life<e.harm*p.party.length*.75&&e.hp>e.damage*1.5||s.battle.round>=14)return engine.retreat();engine.resume();return engine.round()}return engine.state()}
async function kick(){if(autoRunning||busy||screen!=='game'||!s||s.turn!==1||s.phase==='finished')return;autoRunning=true;let guard=0;try{while(screen==='game'&&s.turn===1&&s.phase!=='finished'&&guard++<80){busy=true;renderGame();if(settings.speed!=='instant')await delay(settings.speed==='fast'?80:210);let before=JSON.stringify(s);s=await cpuAction();safeSave();await revealNew(JSON.parse(before));if(JSON.stringify(s)===before){if(s.phase==='ability')s=engine.next();else if(s.phase==='quest')s=await engine.end();else break}}if(guard>=80&&s.turn===1){notice('CPU: limite di sicurezza');if(s.phase==='ability')s=engine.next();if(s.phase==='quest')s=await engine.end();else if(s.phase==='roundEnd')s=await engine.retreat();safeSave()}}catch(e){console.error(e);notice('CPU: '+e.message)}finally{busy=false;autoRunning=false;renderIfGame()}}
