 const x=target.left+target.width/2,y=target.top+target.height*.43, sx=a.left+a.width/2,sy=a.top+a.height/2,R=Math.min(target.width,target.height)*.48,fast=settings.speed==='fast',duration=fast?410:790,wind=fast?.20:.28,travel=(kind==='Ranger'||kind==='Maghi')?.25:0,impact=wind+travel, colors=kind==='claw'?['#ff2c38','#ffd0b7']:kind==='Druidi'?['#7bdf39','#e9ffad']:kind==='Maghi'?['#ff5700','#fff3a0']:['#ffad36','#fff8d0'];
